import{_ as t,b as o,c as n,g as s}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"样例学习","description":"","frontmatter":{"title":"样例学习","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/19.md","filePath":"articles/ai/books/ai-modern-approach/19.md"}'),a={name:"articles/ai/books/ai-modern-approach/19.md"};function l(r,i,g,e,d,_){return o(),n("div",null,[...i[0]||(i[0]=[s('<p>第 19 章深入探讨集成学习方法，核心是如何组合多个基学习器以获得比单一模型更好的泛化性能。重点包括：</p><h2 id="集成学习的基本思想" tabindex="-1">集成学习的基本思想</h2><ul><li><strong>基学习器</strong>：多个弱学习器或中等强度学习器的组合</li><li><strong>多样性</strong>：基模型之间的差异是集成成功的关键</li><li><strong>偏差-方差权衡</strong>：Bagging 主要降低方差，Boosting 主要降低偏差</li></ul><h2 id="bagging-与随机森林" tabindex="-1">Bagging 与随机森林</h2><ul><li><strong>Bagging（Bootstrap Aggregating）</strong>：对训练集进行有放回采样，训练多个基模型，最终投票或平均</li><li><strong>随机森林</strong>：在 Bagging 基础上引入特征子集随机性，进一步增加基模型多样性</li><li>两种随机性（Bootstrap 采样 + 随机特征子集）如何降低过拟合</li></ul><h2 id="boosting" tabindex="-1">Boosting</h2><ul><li><strong>AdaBoost</strong>：迭代训练，每轮调整样本权重，错误样本权重增大</li><li>权重系数 α = 1/2 ln((1-ε)/ε)，其中 ε 为当前分类器错误率</li><li><strong>梯度提升（Gradient Boosting）</strong>、<strong>XGBoost</strong>：基于梯度下降的序列集成</li></ul><h2 id="其他集成方法" tabindex="-1">其他集成方法</h2><ul><li><strong>Stacking</strong>：用元学习器组合多个基模型的预测输出</li><li><strong>Voting</strong>：硬投票与软投票</li><li>交叉验证生成元特征，避免信息泄露</li></ul><h2 id="模型评估" tabindex="-1">模型评估</h2><ul><li>学习曲线（训练误差 vs 验证误差）判断过拟合</li><li>多数投票错误概率的计算</li><li>特征重要性（Gini 不纯度减少 vs 置换精度下降）</li></ul>',11)])])}const u=t(a,[["render",l]]);export{c as __pageData,u as default};
